"use strict";(self.webpackChunkhudi=self.webpackChunkhudi||[]).push([[65131],{5247:(e,t,a)=>{a.r(t),a.d(t,{assets:()=>l,contentTitle:()=>o,default:()=>h,frontMatter:()=>r,metadata:()=>i,toc:()=>c});var i=a(50844),n=a(74848),s=a(28453);const r={title:"Using Apache Hudi with Apache Iceberg: Interoperability via Apache XTable",excerpt:"Choosing Apache Hudi does not mean giving up Apache Iceberg compatibility. Apache XTable translates Hudi table metadata into Iceberg in place, so one copy of data serves every engine.",description:"How Apache XTable lets Iceberg engines and catalogs read Hudi tables as Iceberg by translating table metadata in place \u2014 no data copies, no rewrites.",authors:["sivabalan"],category:"how-to",image:"/assets/images/hudi_stack/pluggable_tf.png",tags:["apache xtable","apache iceberg","interoperability","data lakehouse","table format"]},o=void 0,l={authorsImageUrls:[void 0]},c=[{value:"The Format Lock-In Problem",id:"the-format-lock-in-problem",level:2},{value:"What Is Apache XTable?",id:"what-is-apache-xtable",level:2},{value:"How It Works: Metadata Translation, Not Data Movement",id:"how-it-works-metadata-translation-not-data-movement",level:2},{value:"Hands-On: Exposing a Hudi Table as Iceberg",id:"hands-on-exposing-a-hudi-table-as-iceberg",level:2},{value:"Continuous sync from the ingestion pipeline",id:"continuous-sync-from-the-ingestion-pipeline",level:3},{value:"Registering with Catalogs So Iceberg Engines Find the Table",id:"registering-with-catalogs-so-iceberg-engines-find-the-table",level:2},{value:"What This Architecture Unlocks",id:"what-this-architecture-unlocks",level:2},{value:"Honest Limitations",id:"honest-limitations",level:2},{value:"XTable vs Actually Migrating Formats",id:"xtable-vs-actually-migrating-formats",level:2},{value:"Conclusion",id:"conclusion",level:2},{value:"FAQ",id:"faq",level:2}];function d(e){const t={a:"a",code:"code",em:"em",h2:"h2",h3:"h3",img:"img",li:"li",ol:"ol",p:"p",pre:"pre",strong:"strong",ul:"ul",...(0,s.R)(),...e.components},{PostFAQ:i}=t;return i||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("PostFAQ",!0),(0,n.jsxs)(n.Fragment,{children:[(0,n.jsxs)(t.p,{children:["Yes \u2014 Apache Iceberg engines and catalogs can read Apache Hudi tables. ",(0,n.jsx)(t.a,{href:"https://xtable.apache.org",children:"Apache XTable"})," (incubating) translates Hudi table metadata into Apache Iceberg (and Delta Lake) metadata in place, so a single copy of data on object storage is readable as any of the three formats. No data is copied or rewritten; XTable reads the Hudi table's metadata and writes out the equivalent Iceberg metadata alongside the same Parquet files."]}),"\n",(0,n.jsx)(t.p,{children:"This matters because many teams believe they face a binary choice. Their streaming ingestion, CDC pipelines, and update-heavy workloads point toward Hudi's write-side strengths, but a query engine, BI tool, or managed service in their stack only speaks Iceberg \u2014 so they conclude they must give up one to keep the other. They don't. This post explains how XTable dissolves that constraint, walks through exposing a Hudi table as Iceberg step by step, and covers the limitations you should understand before putting it in production."}),"\n",(0,n.jsx)(t.h2,{id:"the-format-lock-in-problem",children:"The Format Lock-In Problem"}),"\n",(0,n.jsxs)(t.p,{children:["An ",(0,n.jsx)(t.a,{href:"/blog/2026/07/14/what-is-an-open-table-format",children:"open table format"})," is the metadata layer that turns Parquet files on object storage into a transactional table \u2014 the load-bearing component of the ",(0,n.jsx)(t.a,{href:"/blog/2024/07/11/what-is-a-data-lakehouse",children:"data lakehouse"})," architecture. Apache Hudi, Apache Iceberg, and Delta Lake all implement this idea, and all three ultimately describe the same thing: a set of Parquet data files plus metadata recording which files form the table, what schema they follow, and how the table has changed over time."]}),"\n",(0,n.jsx)(t.p,{children:"The friction arises at the edges of the ecosystem. Some engines and managed services support only one format for external tables \u2014 most commonly Iceberg, given its broad catalog and vendor ecosystem. If your organization has standardized its serving layer on such an engine, every table you want to query there apparently needs to be an Iceberg table."}),"\n",(0,n.jsxs)(t.p,{children:["At the same time, Hudi's design center is the write path. Teams pick Hudi for fast upserts and deletes backed by ",(0,n.jsx)(t.a,{href:"/docs/indexes",children:"pluggable, multi-modal indexing"}),", streaming and CDC ingestion, incremental processing, and built-in ",(0,n.jsx)(t.a,{href:"/docs/hudi_stack",children:"table services"})," \u2014 compaction, clustering, cleaning \u2014 that keep tables optimized without separate orchestration. Giving those up to satisfy a read-side format requirement is a real cost, paid on every pipeline, every day."]}),"\n",(0,n.jsx)(t.p,{children:"The choice is false because the formats differ in metadata, not data. If the Parquet files can stay put and only the metadata needs a second representation, no migration is required \u2014 just a translation. That is precisely what Apache XTable does."}),"\n",(0,n.jsx)(t.h2,{id:"what-is-apache-xtable",children:"What Is Apache XTable?"}),"\n",(0,n.jsxs)(t.p,{children:[(0,n.jsx)(t.a,{href:"https://xtable.apache.org",children:"Apache XTable"}),' is an open source project incubating at the Apache Software Foundation (it was previously known as OneTable). In the project\'s own words, it provides "cross-table omni-directional interop between lakehouse table formats." Two properties define it:']}),"\n",(0,n.jsxs)(t.ul,{children:["\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"It is not another table format."})," XTable introduces no new specification for engines to adopt. It provides abstractions and tools for translating existing table format metadata between Apache Hudi, Apache Iceberg, and Delta Lake."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"It translates metadata, not data."})," XTable reads the existing metadata of your table and writes out metadata for one or more other table formats into the same table directory. The Parquet data files are never copied, moved, or rewritten."]}),"\n"]}),"\n",(0,n.jsx)(t.p,{children:"Any of the three formats can act as the source, and you can target one or several formats in a single sync. For this post's scenario, the source is Hudi and the target is Iceberg \u2014 but the same mechanics work Iceberg-to-Hudi, Delta-to-Iceberg, and every other direction."}),"\n",(0,n.jsxs)(t.p,{children:["The Hudi community treats this as a first-class interoperability path: the ",(0,n.jsx)(t.a,{href:"/docs/syncing_xtable",children:"XTable sync documentation"})," covers it, and Hudi 1.1's pluggable table format work goes further by letting XTable supply format adapters inside Hudi's own write path (more on that below)."]}),"\n",(0,n.jsx)(t.h2,{id:"how-it-works-metadata-translation-not-data-movement",children:"How It Works: Metadata Translation, Not Data Movement"}),"\n",(0,n.jsx)(t.p,{children:"Conceptually, every sync run does three things:"}),"\n",(0,n.jsxs)(t.ol,{children:["\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"Read the source metadata."})," XTable reads the Hudi table's timeline and metadata to determine the current state of the table: which data files are live, the schema, partition information, and file-level column statistics."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"Translate to the target model."})," That state is mapped into Iceberg's metadata model \u2014 snapshots, manifests, and table metadata files describing the very same Parquet files."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"Write target metadata alongside."})," The Iceberg metadata is written under the table's base path (in the standard ",(0,n.jsx)(t.code,{children:"metadata/"})," directory Iceberg readers expect), next to Hudi's ",(0,n.jsx)(t.code,{children:".hoodie"})," directory. One directory on storage, two formats' views of it."]}),"\n"]}),"\n",(0,n.jsx)(t.p,{children:"The translation carries more than the file list. Data files are synced along with their column-level statistics and partition metadata, so Iceberg readers keep the file-skipping benefits they expect from Iceberg's own statistics. Schema updates in the source are reflected in the target table metadata. XTable also performs format-appropriate metadata maintenance on the target \u2014 for example, snapshot expiration for Iceberg targets \u2014 so translated metadata doesn't grow without bound."}),"\n",(0,n.jsxs)(t.p,{children:["XTable supports two sync modes. ",(0,n.jsx)(t.strong,{children:"Full sync"})," recomputes the target metadata from the source table's current state. ",(0,n.jsx)(t.strong,{children:"Incremental sync"})," translates only the changes since the last sync, which is more lightweight and performs better, especially on large tables; if incremental sync can't proceed for some reason, XTable automatically falls back to a full sync. In practice you run incremental sync on a schedule (or per commit), and correctness is preserved either way."]}),"\n",(0,n.jsx)(t.h2,{id:"hands-on-exposing-a-hudi-table-as-iceberg",children:"Hands-On: Exposing a Hudi Table as Iceberg"}),"\n",(0,n.jsxs)(t.p,{children:["Suppose you have a Hudi table of orders at ",(0,n.jsx)(t.code,{children:"s3://warehouse/orders"}),", written by a streaming pipeline (Hudi tables created with 0.14.0 or later are supported). Exposing it as Iceberg takes a config file and one command."]}),"\n",(0,n.jsxs)(t.p,{children:["First, get the XTable utilities jar \u2014 build it from ",(0,n.jsx)(t.a,{href:"https://github.com/apache/incubator-xtable",children:"source"})," or download it from the project's GitHub packages. Then describe the translation in a YAML file:"]}),"\n",(0,n.jsx)(t.pre,{children:(0,n.jsx)(t.code,{className:"language-yaml",metastring:'title="my_config.yaml"',children:"sourceFormat: HUDI\ntargetFormats:\n  - ICEBERG\ndatasets:\n  - tableBasePath: s3://warehouse/orders\n    tableName: orders\n    partitionSpec: order_date:VALUE\n"})}),"\n",(0,n.jsxs)(t.p,{children:[(0,n.jsx)(t.code,{children:"sourceFormat"})," names the format to read, ",(0,n.jsx)(t.code,{children:"targetFormats"})," lists one or more formats to produce (you could add ",(0,n.jsx)(t.code,{children:"DELTA"})," to the list to get both at once), and each entry under ",(0,n.jsx)(t.code,{children:"datasets"})," points at a table. ",(0,n.jsx)(t.code,{children:"partitionSpec"})," tells XTable how the Hudi table is partitioned so it can map partitions into Iceberg's partition spec."]}),"\n",(0,n.jsx)(t.p,{children:"Run the sync:"}),"\n",(0,n.jsx)(t.pre,{children:(0,n.jsx)(t.code,{className:"language-shell",children:"java -jar path/to/xtable-utilities-bundled.jar --datasetConfig my_config.yaml\n"})}),"\n",(0,n.jsx)(t.p,{children:"When the run completes, the table's base path contains Iceberg metadata files \u2014 schema, commit history, partitions, and column statistics \u2014 describing the same Parquet files Hudi manages. Re-running the command picks up new Hudi commits incrementally. You can batch many tables into one config, and schedule the job with whatever orchestrator you already use."}),"\n",(0,n.jsx)(t.h3,{id:"continuous-sync-from-the-ingestion-pipeline",children:"Continuous sync from the ingestion pipeline"}),"\n",(0,n.jsxs)(t.p,{children:["If the table is fed by ",(0,n.jsx)(t.a,{href:"/docs/hoodie_streaming_ingestion",children:"Hudi Streamer"}),", you can sync every commit as it lands instead of running a separate job. Add the XTable ",(0,n.jsx)(t.a,{href:"https://github.com/apache/incubator-xtable/tree/main/hudi-support/extensions",children:"extensions jar"})," to the classpath, add ",(0,n.jsx)(t.code,{children:"org.apache.xtable.hudi.sync.OneTableSyncTool"})," to the pipeline's sync classes, and configure the targets:"]}),"\n",(0,n.jsx)(t.pre,{children:(0,n.jsx)(t.code,{children:"hoodie.onetable.formats.to.sync=ICEBERG\nhoodie.onetable.target.metadata.retention.hr=168\n"})}),"\n",(0,n.jsx)(t.p,{children:"With this in place, the Iceberg view advances in lockstep with Hudi commits, and the freshness gap between the two views effectively disappears."}),"\n",(0,n.jsx)(t.h2,{id:"registering-with-catalogs-so-iceberg-engines-find-the-table",children:"Registering with Catalogs So Iceberg Engines Find the Table"}),"\n",(0,n.jsxs)(t.p,{children:["Producing Iceberg metadata is half the job; Iceberg-speaking engines discover tables through a catalog, so the synced table needs to be registered. XTable's ",(0,n.jsx)(t.a,{href:"https://xtable.apache.org/docs/catalogs-index",children:"catalog integration docs"})," cover registering synced target tables with Hive Metastore, AWS Glue Data Catalog, Unity Catalog, and BigLake Metastore \u2014 registration is an explicit step after the sync. XTable also supports keeping table metadata synchronized across catalogs such as Hive Metastore and Glue."]}),"\n",(0,n.jsx)(t.p,{children:"Once registered, the table is, from the engine's point of view, simply an Iceberg table. Cloud warehouses and services that can query Iceberg tables \u2014 Snowflake, Google BigQuery, Amazon Athena and Redshift, among others \u2014 can read it through their Iceberg support, subject to each vendor's own capabilities and requirements. Distributed SQL engines like Trino and Presto query it through their Iceberg connectors. None of them need to know the table is written by Hudi."}),"\n",(0,n.jsxs)(t.p,{children:["Hudi separately ships its own ",(0,n.jsx)(t.a,{href:"/docs/syncing_metastore",children:"catalog sync tools"})," for the Hudi-native view of the table, so the same data can be discoverable both as a Hudi table (for engines with Hudi support) and as an Iceberg table (for everything else)."]}),"\n",(0,n.jsx)(t.h2,{id:"what-this-architecture-unlocks",children:"What This Architecture Unlocks"}),"\n",(0,n.jsx)(t.p,{children:"Put together, the pattern looks like this: write once with Hudi, serve everywhere."}),"\n",(0,n.jsxs)(t.ul,{children:["\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"Ingestion"})," uses Hudi's strengths \u2014 record-level indexes for fast upserts and deletes, streaming and CDC ingestion, non-blocking table services, incremental pulls for downstream pipelines. See ",(0,n.jsx)(t.a,{href:"/docs/table_types",children:"table types"})," for how Copy-on-Write and Merge-on-Read trade write latency against read cost."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"Storage"})," holds exactly one copy of the data, as Parquet files on object storage, with both Hudi and Iceberg metadata describing it."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"Serving"})," spans every engine in the organization: Hudi-native engines read the Hudi view; Iceberg-only engines and services read the Iceberg view; nothing is exported, duplicated, or re-ingested."]}),"\n"]}),"\n",(0,n.jsx)(t.p,{children:'There is no second pipeline to operate, no divergence between "the Hudi copy" and "the Iceberg copy," and no per-engine storage bill. Format choice stops being an organization-wide standardization battle and becomes a per-workload decision about write-path capabilities.'}),"\n",(0,n.jsxs)(t.p,{children:["This direction is also converging with Hudi itself. Starting with Hudi 1.1, a ",(0,n.jsx)(t.a,{href:"/docs/hudi_stack",children:"pluggable table format framework"})," decouples Hudi's storage engine \u2014 timeline, indexes, concurrency control, table services \u2014 from the metadata format written for data files, with XTable supplying format adapters for Iceberg and Delta Lake. The trajectory is that maintaining Iceberg metadata becomes part of the Hudi write path itself, rather than a companion sync."]}),"\n",(0,n.jsxs)(t.p,{children:[(0,n.jsx)(t.img,{alt:"Hudi storage engine with pluggable format adapters via Apache XTable",src:a(23448).A+"",width:"894",height:"610"}),"\n",(0,n.jsx)("p",{align:"center",children:"Figure: Hudi's storage engine with format adapters for Iceberg and Delta Lake via Apache XTable"})]}),"\n",(0,n.jsx)(t.h2,{id:"honest-limitations",children:"Honest Limitations"}),"\n",(0,n.jsx)(t.p,{children:"XTable is a pragmatic tool, and it's worth being precise about its boundaries."}),"\n",(0,n.jsxs)(t.ul,{children:["\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"It's read-side interoperability."})," The translated Iceberg metadata gives Iceberg engines a read view of the table. Writes should continue to go through Hudi; XTable does not merge concurrent writes made independently in two formats to the same files."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"Freshness trails the sync cadence."})," The Iceberg view reflects the table as of the last sync, so it lags the latest Hudi commit by up to the sync interval. Per-commit sync via the Hudi Streamer extension closes this gap; a nightly cron does not. Decide the cadence based on how fresh the Iceberg consumers need to be."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"Merge-on-Read log files aren't translated."})," XTable syncs the underlying Parquet base files; Hudi log files (and, in the other directions, Delta deletion vectors and Iceberg delete files) are not captured. For a Hudi MoR table, the target format therefore sees the read-optimized view \u2014 records still sitting in log files become visible to Iceberg readers after compaction. Copy-on-Write tables don't have this caveat."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"Source table requirements."})," XTable requires Hudi 0.14.0 or later and depends on Hudi's metadata table; check the ",(0,n.jsx)(t.a,{href:"https://xtable.apache.org/docs/features-and-limitations",children:"XTable docs"})," for current prerequisites and configuration."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"Feature-mapping edge cases exist."})," The formats are not feature-identical, and format-specific constructs don't always have an exact counterpart on the other side (for example, Delta generated columns as a source have limited support). Each format's advanced features work fully only in that format's native engines."]}),"\n"]}),"\n",(0,n.jsx)(t.p,{children:'None of these undermine the core pattern \u2014 most production uses are exactly "Hudi writes, Iceberg engines read" \u2014 but they should inform table type, sync cadence, and which features you rely on across the boundary.'}),"\n",(0,n.jsx)(t.h2,{id:"xtable-vs-actually-migrating-formats",children:"XTable vs Actually Migrating Formats"}),"\n",(0,n.jsx)(t.p,{children:'XTable also answers the "convert Hudi to Iceberg" question, but it\'s worth distinguishing two intents:'}),"\n",(0,n.jsxs)(t.ul,{children:["\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"You need Iceberg read compatibility while keeping Hudi's write path."})," Use XTable in continuous incremental sync mode, as described above. This is the common case, and nothing is migrated \u2014 both views persist indefinitely."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"You genuinely want to switch formats."})," XTable can serve as a low-risk migration mechanism: sync the table, repoint readers at the Iceberg view, validate, and only then move writers to an Iceberg-native write path \u2014 all without rewriting data files. Because the translation is omni-directional, the door swings both ways: teams migrating an Iceberg or Delta table ",(0,n.jsx)(t.em,{children:"to"})," Hudi to gain its ingestion and table-service capabilities follow the same steps with source and target swapped."]}),"\n"]}),"\n",(0,n.jsxs)(t.p,{children:["The practical takeaway from the ",(0,n.jsx)(t.a,{href:"/blog/2026/07/14/what-is-an-open-table-format",children:"open table format landscape"})," applies here: pick the format whose write path fits each workload, and let interoperability handle the rest. Migration becomes a repointing exercise, not a data-movement project."]}),"\n",(0,n.jsx)(t.h2,{id:"conclusion",children:"Conclusion"}),"\n",(0,n.jsx)(t.p,{children:"The premise behind \"we can't use Hudi because our engine only reads Iceberg\" no longer holds. Hudi, Iceberg, and Delta Lake all describe Parquet files with metadata, and Apache XTable translates that metadata in any direction \u2014 incrementally, in place, without copying data. A table written with Hudi's indexing, streaming ingestion, and table services can be registered in a catalog and queried by any Iceberg-capable engine as an ordinary Iceberg table, while Hudi-native engines keep the full-fidelity view. With Hudi's pluggable table format framework pushing this further into the write path itself, choosing Hudi is not a bet against Iceberg \u2014 it's a way to get Hudi's write-side strengths and Iceberg's read-side reach from a single copy of your data."}),"\n",(0,n.jsxs)(t.p,{children:["To try it, start with the ",(0,n.jsx)(t.a,{href:"/docs/syncing_xtable",children:"Hudi XTable sync guide"})," and the ",(0,n.jsx)(t.a,{href:"https://xtable.apache.org",children:"Apache XTable documentation"}),"."]}),"\n",(0,n.jsx)(t.h2,{id:"faq",children:"FAQ"}),"\n",(0,n.jsx)(i,{heading:null,items:[{question:"Can Iceberg engines read Hudi tables?",answer:"Yes. Apache XTable translates a Hudi table's metadata into Apache Iceberg metadata written alongside the same Parquet data files. Once that Iceberg metadata is registered in a catalog, any engine with Iceberg read support can query the table as an ordinary Iceberg table."},{question:"Can Snowflake read Hudi tables?",answer:"Not directly, but Snowflake can query Iceberg tables, and Apache XTable can expose a Hudi table as Iceberg by translating its metadata in place. After syncing with XTable and registering the Iceberg metadata, Snowflake reads the table through its Iceberg support, subject to Snowflake's own Iceberg capabilities and requirements."},{question:"Does XTable copy my data?",answer:"No. XTable translates only table metadata. It reads the source format's metadata and writes out the target format's metadata into the same table directory, while the Parquet data files stay exactly where they are. One copy of data serves all synced formats."},{question:"Can I convert a Hudi table to Iceberg?",answer:"Yes. Running XTable with sourceFormat HUDI and targetFormats ICEBERG produces complete Iceberg metadata for the table without rewriting any data files. You can keep both views in sync continuously, or use the translation as a migration step by repointing readers and writers to the Iceberg view after validating it."},{question:"Is Apache XTable production ready?",answer:"Apache XTable is an incubating project at the Apache Software Foundation, which is a statement about ASF governance maturity rather than code quality. It is used in real deployments and its metadata-only design is low risk since source data and metadata are never modified, but you should validate it against your own tables and review the documented limitations, such as Merge-on-Read log files not being captured, before relying on it in production."},{question:"Does XTable work with Hudi Merge-on-Read tables?",answer:"Partially. XTable syncs the Parquet base files but not Hudi log files, so the Iceberg view of a Merge-on-Read table corresponds to the read-optimized view. Records still in log files become visible to Iceberg readers after compaction. Copy-on-Write tables do not have this caveat."}]})]})}function h(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(d,{...e})}):d(e)}},23448:(e,t,a)=>{a.d(t,{A:()=>i});const i=a.p+"assets/images/pluggable_tf-c14c58c53931f285bdfe832c5014361a.png"},28453:(e,t,a)=>{a.d(t,{R:()=>r,x:()=>o});var i=a(96540);const n={},s=i.createContext(n);function r(e){const t=i.useContext(s);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:r(e.components),i.createElement(s.Provider,{value:t},e.children)}},50844:e=>{e.exports=JSON.parse('{"permalink":"/blog/2026/07/28/using-hudi-with-apache-iceberg-via-xtable","editUrl":"https://github.com/apache/hudi/edit/asf-site/website/blog/blog/2026-07-28-using-hudi-with-apache-iceberg-via-xtable.md","source":"@site/blog/2026-07-28-using-hudi-with-apache-iceberg-via-xtable.md","title":"Using Apache Hudi with Apache Iceberg: Interoperability via Apache XTable","description":"How Apache XTable lets Iceberg engines and catalogs read Hudi tables as Iceberg by translating table metadata in place \u2014 no data copies, no rewrites.","date":"2026-07-28T00:00:00.000Z","tags":[{"inline":true,"label":"apache xtable","permalink":"/blog/tags/apache-xtable"},{"inline":true,"label":"apache iceberg","permalink":"/blog/tags/apache-iceberg"},{"inline":true,"label":"interoperability","permalink":"/blog/tags/interoperability"},{"inline":true,"label":"data lakehouse","permalink":"/blog/tags/data-lakehouse"},{"inline":true,"label":"table format","permalink":"/blog/tags/table-format"}],"readingTime":13.09,"hasTruncateMarker":false,"authors":[{"name":"Sivabalan Narayanan","url":"https://www.linkedin.com/in/sivabalan-narayanan-1040b45/","imageURL":"/assets/images/authors/sivabalan.jpg","key":"sivabalan","page":null}],"frontMatter":{"title":"Using Apache Hudi with Apache Iceberg: Interoperability via Apache XTable","excerpt":"Choosing Apache Hudi does not mean giving up Apache Iceberg compatibility. Apache XTable translates Hudi table metadata into Iceberg in place, so one copy of data serves every engine.","description":"How Apache XTable lets Iceberg engines and catalogs read Hudi tables as Iceberg by translating table metadata in place \u2014 no data copies, no rewrites.","authors":["sivabalan"],"category":"how-to","image":"/assets/images/hudi_stack/pluggable_tf.png","tags":["apache xtable","apache iceberg","interoperability","data lakehouse","table format"]},"unlisted":false,"lastUpdatedAt":1785219924000,"prevItem":{"title":"Migrating from Parquet to Apache Hudi: A Practical Guide","permalink":"/blog/2026/07/29/migrating-from-parquet-to-hudi"},"nextItem":{"title":"Open Table Format vs Data Lakehouse: What\'s the Difference?","permalink":"/blog/2026/07/24/open-table-format-vs-data-lakehouse"}}')}}]);